import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.*;

public class Main {
  public static void main(String[] args) {
    InputStream inputStream = System.in;
    OutputStream outputStream = System.out;
    InputReader in = new InputReader(inputStream);
    PrintWriter out = new PrintWriter(outputStream);
    TaskF solver = new TaskF();
    solver.solve(1, in, out);
    out.close();
  }

  static class TaskF {
    public void solve(int testNumber, InputReader in, PrintWriter out) {
      int n = in.readInt();
      char[] s = in.readString().toCharArray();
      int[] beauty = new int[n];
      int totalBeauty = 0;
      for (int i = 0; i < n; ++i) {
        beauty[i] = in.readInt();
        totalBeauty += beauty[i];
      }

      int half = n / 2;
      int[] charOccurrences = new int[128];
      int[] equalPairIndices = new int[half];
      int equalCount = 0;
      for (int i = 0; i < half; ++i) {
        if (s[i] == s[n - 1 - i]) {
          equalPairIndices[equalCount++] = i;
          charOccurrences[s[i]]++;
        }
      }

      char mostCommonChar = 'a';
      for (int c = 0; c < 128; c++) {
        if (charOccurrences[c] > charOccurrences[mostCommonChar]) {
          mostCommonChar = (char) c;
        }
      }

      int ans = totalBeauty;
      for (int j = 0; j < equalCount; ++j) {
        int idx = equalPairIndices[j];
        ans -= Math.min(beauty[idx], beauty[n - 1 - idx]);
      }

      if (charOccurrences[mostCommonChar] > equalCount / 2) {
        int[] penalties = new int[half];
        int penaltyCount = 0;
        for (int i = 0; i < half; ++i) {
          if (s[i] != s[n - 1 - i] && s[i] != mostCommonChar && s[n - 1 - i] != mostCommonChar) {
            penalties[penaltyCount++] = Math.min(beauty[i], beauty[n - 1 - i]);
          }
        }
        Arrays.sort(penalties, 0, penaltyCount);
        int rem = 2 * charOccurrences[mostCommonChar] - equalCount;
        for (int i = 0; i < rem; ++i) {
          ans -= penalties[i];
        }
      }

      out.println(ans);
    }
  }

  static class InputReader {
    private InputStream stream;
    private byte[] buf = new byte[1024];
    private int curChar;
    private int numChars;
    private SpaceCharFilter filter;

    public InputReader(InputStream stream) {
      this.stream = stream;
    }

    public int read() {
      if (numChars == -1) throw new InputMismatchException();
      if (curChar >= numChars) {
        curChar = 0;
        try {
          numChars = stream.read(buf);
        } catch (IOException e) {
          throw new InputMismatchException();
        }
        if (numChars <= 0) return -1;
      }
      return buf[curChar++];
    }

    public int readInt() {
      int c = read();
      while (isSpaceChar(c)) c = read();
      int sgn = 1;
      if (c == '-') { sgn = -1; c = read(); }
      int res = 0;
      do {
        if (c < '0' || c > '9') throw new InputMismatchException();
        res *= 10;
        res += c - '0';
        c = read();
      } while (!isSpaceChar(c));
      return res * sgn;
    }

    public String readString() {
      int c = read();
      while (isSpaceChar(c)) c = read();
      StringBuilder res = new StringBuilder();
      do {
        if (Character.isValidCodePoint(c)) res.appendCodePoint(c);
        c = read();
      } while (!isSpaceChar(c));
      return res.toString();
    }

    public boolean isSpaceChar(int c) {
      if (filter != null) return filter.isSpaceChar(c);
      return isWhitespace(c);
    }

    public static boolean isWhitespace(int c) {
      return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    public interface SpaceCharFilter {
      boolean isSpaceChar(int ch);
    }
  }
}
